*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gParamObj = new Array(2);
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.pageSize = 50; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.gNOTI_SVC_ID;
scwin.vScrenID = "ULDSTF30309.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    $c.stf.Combo_CBDataSet(cmb_PerPage);
};
scwin.initPage = function() {
    var ToDay = $c.ut.cGetToday2();
    $c.stf.setObjectValue(edt_EDATE, ToDay);
    var vSDATE = $c.ut.calcMonth(ToDay, -6);
    $c.stf.setObjectValue(edt_SDATE, vSDATE);
    $c.stf.showObj(label_5, false);
    $c.stf.showObj(cmb_SMSGBN, false);
    if (scwin.gDepCd == '2220' || scwin.gDepCd == '3220' || scwin.gDepCd == '3B10' || scwin.gDepCd == 'ZSYS') {
        $c.stf.showObj(label_5, true);
        $c.stf.showObj(cmb_SMSGBN, true);
    } else {
        $c.stf.setObjectValue(cmb_SMSGBN, '1');
    }
};
scwin.fn_New = async function() {
    if (scwin.gDepCd == '2220' || scwin.gDepCd == '3220' || scwin.gDepCd == '3B10' || scwin.gDepCd == 'ZSYS') {
        if ($c.stf.getObjectValue(cmb_SMSGBN) == "") {
            $c.win.alert("메시지 구분을 선택하세요.");
            cmb_SMSGBN.focus();
            return false;
        }
    }
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return false;
    }
    var msgGbn;
    msgGbn = $c.stf.getObjectValue(cmb_SMSGBN);
    await $c.frame.CreateDialogFrame("SENDSMS_NEW", "/bizspt/ULDSTF30308.gfm?MSG_GBN=" + msgGbn, "문자보내기", 200, 50, 800, 665 + 30, "window");
};
scwin.fn_readSendSMS = function(row, colid) {
    if (colid == "TITLE") {
        scwin.gNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
        var url = "/SmsMgt.do?method=readSendSMSInfo" + "&inputMessageId=SMS_INFO_INOUT" + "&outputMessageId=SMS_INFO_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        //alert(url);
        dts_Master.DataID = encodeURI(url);
        dts_Master.Reset();
        var urlReceiver = "/EmailMgt.do?method=listSendReceiver" + "&inputMessageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        dts_Receiver.DataID = encodeURI(urlReceiver);
        dts_Receiver.Reset();
    }
};
scwin.fn_Search = function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return;
    }
    scwin.vCurrPageNo = 0;

    /*
    var trstkSubmitYn;

    if ( gDepCd == "2220"  || gDepCd == "3220" || gDepCd == "3B10" ) {	
    	trstkSubmitYn = "Y";
    } else if ( gDepCd == "ZSYS"  ) {	
    	trstkSubmitYn = "A";
    } else {
    	trstkSubmitYn = "N";
    }	
    */


    var url = "/NoteMgt.do?method=listSendNote";
    url += "&MDTYPE=2"; // 알림매체타입, SMS= 2
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url = "/NoteMgt.do?method=listSendNote";
    url += "&MDTYPE=2"; // 알림매체타입, SMS= 2
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};



// 문자 재발송
scwin.fn_openNew = async function(row) {
    //if ( js_svrGubun == 'dr') {
    //	alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
    //	return;
    //}

    var vNOTI_SVC_ID = '';
    var inAddTyp = 'Y';

    //if (inAddTyp == 'Y') {
    vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
    //}

    //alert(vNOTI_SVC_ID);		

    var url = "";
    url = "/bizspt/ULDSTF30308.gfm?";
    url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
    url += "&ADD_INPUT=" + inAddTyp;
    url += "&frameID=" + frame.FrameID;
    if (scwin.fn_setParam(vNOTI_SVC_ID, inAddTyp)) {
        // formal arguments
        //frame.Provider("../../").GWinOpen("ULDSTF30308", url, "문자 재발송", 200, 10, 790, 750+30,"");
        await $c.frame.CreateDialogFrame("SENDSMS_RESEND", url, "문자 다시보내기", 200, 50, 800, 665 + 30, "window");
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.canDel = 'Y'; //하나만 삭제 하도록 한다.
scwin.noti_id = ''; //삭제 키 값
scwin.del_no = 0; //삭제 하려는 NO. alert 표시를 위해
scwin.checkFlagVal = function(row, colid) {
    chkVal = dts_Grid.getCellData(row, "CHK_FLAG");
    delYN = dts_Grid.getCellData(row, "FLAG");
    empNo = dts_Grid.getCellData(row, "SND_CHRG_EMP_NO");
    depCd = dts_Grid.getCellData(row, "DEP_CD");
    if (scwin.canDelete(empNo, depCd)) {
        if (chkVal == '1') {
            if (delYN == 'Y') {
                if (scwin.canDel == 'Y') {
                    scwin.canDel = 'N';
                    scwin.noti_id = dts_Grid.getCellData(row, "NOTI_SVC_ID");
                    scwin.del_no = row;
                    scwin.setDelData(scwin.noti_id, js_emp_no);
                } else {
                    $c.win.alert('삭제는 한건씩만 가능 합니다.');
                    dts_Grid.setCellData(row, "CHK_FLAG", 0);
                }
            } else {
                $c.win.alert('기 삭제, 발송된 건은 삭제 할 수 없습니다.');
                dts_Grid.setCellData(row, "CHK_FLAG", 0);
            }
        } else {
            scwin.resetDelFlag();
        }
    } else {
        dts_Grid.setCellData(row, "CHK_FLAG", 0);
        $c.win.alert('보낸이거나 보낸이와 같은 팀원만 삭제 가능합니다.');
    }
};
scwin.resetDelFlag = function() {
    scwin.canDel = 'Y';
    scwin.del_no = 0;
    dts_delInfo.removeAll();
};


//KBoY 2017-08-28
//당사자이거나 보낸이와 같은 팀인 경우에만 삭제 가능.
scwin.canDelete = function(vEmpNo, vDepCd) {
    if (vEmpNo == js_emp_no) {
        return true;
    } else {
        if (vDepCd == js_dep_cd) {
            return true;
        } else {
            return false;
        }
    }
};




//KBoY 2017-08-28
//삭제할 목록 ID와 삭제한 EMP_NO를 세팅한다.
scwin.setDelData = function(vNotiId, vEmpNo) {
    dts_delInfo.insertRow();
    dts_delInfo.setCellData(1, "NOTI_SVC_ID", vNotiId);
    dts_delInfo.setCellData(1, "SND_CHRG_EMP_NO", vEmpNo);
};



//KBoY 2017-08-28
scwin.doDel = function() {
    var msg = scwin.del_no + '번을 삭제하시겠습니까?';
    if (scwin.isChecked()) {
        if (confirm(msg)) {
            scwin.delSMS();
        }
    }
};
scwin.isChecked = function() {
    if (scwin.noti_id == '' || scwin.del_no == 0) {
        $c.win.alert('삭제할 예약 서비스를 선택하십시오');
        return false;
    } else {
        return true;
    }
};
scwin.delSMS = function() {
    var url = "/SmsMgt.do?method=deleteSMS" + "&USR_ID=" + js_id + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_del.Action = url;
    trs_del.KeyName = "toinb_dataid4";
    trs_del.KeyValue = "JSP(I:pInputVal=dts_delInfo)";
    trs_del.post();
};
scwin.setDataSet = function() {
    dts_delInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SMS_INFO_INOUT"; //전체부서조직
    dts_delInfo.reset();
};



//S:SDK_SMS_SEND테이블에서 삭제하다가 에러
//N:TBLD_CORP_NOTI_SVC 삭제자 정보 업데이트하려다 에러
//E:SDK_SMS_SEND 삭제 시도할때 에러(그냥 시작하기도전에 에러)
scwin.showResult = function(ver) {
    if (ver == "S" || ver == "N" || ver == "E") {
        $c.win.alert('삭제 처리 중 오류가 발생하였습니다. 관리자에게 문의하세요. errorCode :' + ver);
    } else if (ver == "0") {
        $c.win.alert('기 삭제되었거나, 이미 발송 되었습니다. 관리자에게 문의하세요. errorCode :' + ver);
    } else {
        $c.win.alert('요청한 삭제 건에 대한 ' + ver + '건의 예약 메세지를 삭제하였습니다.');
    }
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_receiver_cnt, "총 : " + rowcount + " 건");
};
scwin.cmb_PerPage_OnSelChange2 = function() {
    var vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
    scwin.pageSize = vPerPage;
    //alert(pageSize);	
    scwin.fn_Search();
};
scwin.cmb_PerPage_OnSelected = function() {

};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    /*
    var vTotalCnt = dts_Grid.NameString(1, "CNT");	
    //FillGridHeader2(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page);		

    //alert(pageNoCnt +", "+getObjectValue(cmb_PerPage)+", "+vTotalCnt);
    //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
    FillGridHeader(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page, 743);		

    */

    if (dts_Grid.errorMsg) {
        $c.win.alert("OnLoadCompleted Error => " + dts_Grid.errorMsg);
    } else {
        if (scwin.pageSize != '0') {
            if (scwin.vCurrPageNo == 0) {
                scwin.vCurrPageNo = 1;
                scwin.totalCnt = dts_Grid.getCellData(0, "CNT");
            }
        } else {
            scwin.totalCnt = rowcount;
        }
        //alert(pageNoCnt +", "+pageSize+", "+totalCnt);
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
    }
    $c.cm.CloseWin(scwin.totalCnt, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (colid == "TITLE") {
        scwin.fn_readSendSMS(row, colid);
    }
};
scwin.img_new_onclick = function() {
    scwin.fn_New();
};
scwin.cmb_SMSGBN_OnSelChange = function() {

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    scwin.fn_SetCode();
    scwin.initPage();
    scwin.fn_Search();
    scwin.setDataSet();
};
scwin.btn_del_onclick = function() {
    scwin.doDel();
};
scwin.trs_del_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "전송");
    $c.win.alert(msg);
    $c.stf.alert_error(trs_del);
};
scwin.trs_del_OnSuccess = function() {
    //	var msg = getMessageParam("MSG-A001", "전송");
    scwin.showResult(trs_del.ErrorMsg);
    scwin.resetDelFlag();
    scwin.fn_Search();
};
scwin.grd_Grid_OnCheckClick = function(col, colid, bCheck) {
    if (colid == "CHK_FLAG") {
        //alert(col+":"+colid+":"+bCheck);
        scwin.checkFlagVal(col, colid);
    }
};
